exercises.solution:
function formatarReais(centavos) {
  return `R$ ${(centavos / 100).toFixed(2).replace('.', ',')}`;
}

function descreverEntrega(compra) {
  if (compra >= 15000) {
    return 'entrega grátis';
  } else {
    return `entrega de ${formatarReais(1200)}`;
  }
}

console.log(`${formatarReais(12990)}: ${descreverEntrega(12990)}`);
console.log(`${formatarReais(15000)}: ${descreverEntrega(15000)}`);
console.log(`${formatarReais(20350)}: ${descreverEntrega(20350)}`);

